ALTER TABLE public.templates ADD COLUMN shared_team_ids uuid[] NOT NULL DEFAULT '{}', ADD COLUMN copied_from_id uuid, ADD COLUMN copied_from_author uuid;
ALTER TABLE public.resource_templates ADD COLUMN shared_team_ids uuid[] NOT NULL DEFAULT '{}', ADD COLUMN copied_from_id uuid, ADD COLUMN copied_from_author uuid;
CREATE TABLE public.team_library_copies(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,request_key uuid NOT NULL,source_kind text NOT NULL,source_id uuid NOT NULL,target_kind text NOT NULL,target_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,request_key));
GRANT SELECT ON public.team_library_copies TO authenticated; GRANT ALL ON public.team_library_copies TO service_role; ALTER TABLE public.team_library_copies ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own copy receipts" ON public.team_library_copies FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.share_team_library_item(_kind text,_id uuid,_teams uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE own uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'forbidden'; END IF; IF _kind='blueprint' THEN SELECT created_by INTO own FROM templates WHERE id=_id AND team_id IS NOT NULL; ELSIF _kind='resource_template' THEN SELECT created_by INTO own FROM resource_templates WHERE id=_id AND team_id IS NOT NULL; ELSE RAISE EXCEPTION 'unsupported_type'; END IF; IF own IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'forbidden'; END IF;
IF EXISTS(SELECT 1 FROM unnest(coalesce(_teams,'{}')) x WHERE NOT public.team_channel_access(x)) THEN RAISE EXCEPTION 'forbidden'; END IF;
IF _kind='blueprint' THEN UPDATE templates SET shared_team_ids=coalesce(_teams,'{}') WHERE id=_id; ELSE UPDATE resource_templates SET shared_team_ids=coalesce(_teams,'{}') WHERE id=_id; END IF;
PERFORM public.team_log((CASE WHEN _kind='blueprint' THEN (SELECT team_id FROM templates WHERE id=_id) ELSE (SELECT team_id FROM resource_templates WHERE id=_id) END),'library.share',_id,jsonb_build_object('teams',_teams,'kind',_kind)); END $$;
CREATE FUNCTION public.team_library_items(_team uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.team_channel_access(_team) THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN (SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT jsonb_build_object('id',t.id,'kind','blueprint','title',t.title,'author',(SELECT full_name FROM profiles WHERE id=t.created_by),'description',t.description_en,'description_es',t.description_es,'shared_teams',CASE WHEN t.created_by=auth.uid() THEN to_jsonb(t.shared_team_ids) ELSE '[]'::jsonb END,'mine',t.created_by=auth.uid(),'content',jsonb_build_object('checklist',t.checklist,'invite_en',t.invite_script_en,'invite_es',t.invite_script_es)) x FROM templates t WHERE _team=ANY(t.shared_team_ids)
UNION ALL SELECT jsonb_build_object('id',t.id,'kind','resource_template','target',t.target,'title',coalesce(nullif(t.title_en,''),t.title_es),'author',(SELECT full_name FROM profiles WHERE id=t.created_by),'description',t.description_en,'description_es',t.description_es,'shared_teams',CASE WHEN t.created_by=auth.uid() THEN to_jsonb(t.shared_team_ids) ELSE '[]'::jsonb END,'mine',t.created_by=auth.uid(),'content',t.structure) FROM resource_templates t WHERE _team=ANY(t.shared_team_ids)) q); END $$;
CREATE FUNCTION public.my_library_sources() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT jsonb_build_object('id',id,'kind','blueprint','title',title,'shared_teams',shared_team_ids) x FROM templates WHERE created_by=auth.uid() AND team_id IS NOT NULL UNION ALL SELECT jsonb_build_object('id',id,'kind','resource_template','title',coalesce(nullif(title_en,''),title_es),'shared_teams',shared_team_ids) FROM resource_templates WHERE created_by=auth.uid() AND team_id IS NOT NULL) q $$;
CREATE FUNCTION public.copy_team_library_item(_team uuid,_kind text,_id uuid,_destination uuid,_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; temp_id uuid; r resource_templates; t templates; result jsonb; cached team_library_copies; BEGIN IF NOT public.team_channel_access(_team) OR NOT public.team_channel_owner(_destination) THEN RAISE EXCEPTION 'forbidden'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||_request,0)); SELECT * INTO cached FROM team_library_copies WHERE user_id=auth.uid() AND request_key=_request; IF FOUND THEN IF cached.source_id<>_id OR cached.source_kind<>_kind THEN RAISE EXCEPTION 'retry_mismatch'; END IF; RETURN jsonb_build_object('id',cached.target_id,'target',cached.target_kind); END IF;
IF _kind='blueprint' THEN SELECT * INTO t FROM templates WHERE id=_id AND _team=ANY(shared_team_ids) FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'not_shared'; END IF;
INSERT INTO templates(team_id,created_by,title,description_en,description_es,theme,default_duration_minutes,default_capacity,visibility_default,checklist,invite_script_en,invite_script_es,followup_script_en,followup_script_es,is_published,category,category_label,default_mode,default_price_cents,cover_style,copied_from_id,copied_from_author) VALUES(_destination,auth.uid(),t.title,t.description_en,t.description_es,t.theme,t.default_duration_minutes,t.default_capacity,'team',t.checklist,t.invite_script_en,t.invite_script_es,t.followup_script_en,t.followup_script_es,false,t.category,t.category_label,t.default_mode,t.default_price_cents,t.cover_style,t.id,t.created_by) RETURNING id INTO new_id; result:=jsonb_build_object('id',new_id,'target','blueprint');
ELSIF _kind='resource_template' THEN SELECT * INTO r FROM resource_templates WHERE id=_id AND _team=ANY(shared_team_ids) FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'not_shared'; END IF;
INSERT INTO resource_templates(team_id,kind,target,title_en,title_es,description_en,description_es,structure,created_by,copied_from_id,copied_from_author) VALUES(_destination,r.kind,r.target,r.title_en,r.title_es,r.description_en,r.description_es,r.structure,auth.uid(),r.id,r.created_by) RETURNING id INTO temp_id;
result:=public.use_resource_template(temp_id,_destination); new_id:=(result->>'id')::uuid;
ELSE RAISE EXCEPTION 'unsupported_type'; END IF;
INSERT INTO team_library_copies(user_id,request_key,source_kind,source_id,target_kind,target_id) VALUES(auth.uid(),_request,_kind,_id,result->>'target',new_id); PERFORM public.team_log(_destination,'library.copy',new_id,jsonb_build_object('source',_id,'kind',_kind)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.share_team_library_item(text,uuid,uuid[]),public.team_library_items(uuid),public.my_library_sources(),public.copy_team_library_item(uuid,text,uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.share_team_library_item(text,uuid,uuid[]),public.team_library_items(uuid),public.my_library_sources(),public.copy_team_library_item(uuid,text,uuid,uuid,uuid) TO authenticated;
CREATE POLICY "Explicit private blueprint source" ON public.templates AS RESTRICTIVE FOR SELECT TO authenticated USING(team_id IS NULL OR created_by=auth.uid() OR EXISTS(SELECT 1 FROM unnest(shared_team_ids) x WHERE public.team_channel_access(x)));
CREATE POLICY "Explicit private resource template source" ON public.resource_templates AS RESTRICTIVE FOR SELECT TO authenticated USING(team_id IS NULL OR created_by=auth.uid() OR EXISTS(SELECT 1 FROM unnest(shared_team_ids) x WHERE public.team_channel_access(x)));
DO $$ DECLARE f record; d text; BEGIN FOR f IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('invite_team_member','revoke_team_invite','team_invites_list','change_member_role','set_member_suspension') LOOP d:=pg_get_functiondef(f.oid); d:=replace(replace(d,'public.team_capability(_team, ''members'')','public.team_channel_owner(_team)'),'public.team_capability(_team, ''invites'')','public.team_channel_owner(_team)'); d:=replace(d,'public.team_capability(_inv.team_id, ''invites'')','public.team_channel_owner(_inv.team_id)'); EXECUTE d; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.reset_join_code(_team uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; BEGIN IF NOT public.team_channel_owner(_team) THEN RAISE EXCEPTION 'forbidden'; END IF; UPDATE teams SET join_code=upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)) WHERE id=_team RETURNING join_code INTO c; RETURN c; END $$;